import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ChampionshipTitleProps = Record<string, any>;

const ChampionshipTitle: React.FC<ChampionshipTitleProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "2026 CHAMPION",
  subtitleText = "JARED MAPLES",
  primaryColor = "#FFD700", // Gold
  secondaryColor = "#FFFFFF",
  accentColor = "#FFD700",
  titleSize = 140,
  subtitleSize = 60,
}) => {
  
  {/* Load Google Fonts */ }
  useFontLoader(["Oswald", "Montserrat"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animations ---

  // 1. Title Entrance (Spring)
  const titleEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, stiffness: 80, mass: 1.2 },
  });

  // 2. Separator Line Expansion
  const lineEntrance = spring({
    frame: frame - 15,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  // 3. Subtitle Entrance (Spring with delay)
  const subtitleEntrance = spring({
    frame: frame - 20,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // Interpolations
  const titleY = interpolate(titleEntrance, [0, 1], [100, 0]);
  const titleOpacity = interpolate(titleEntrance, [0, 1], [0, 1]);
  
  const lineWidth = interpolate(lineEntrance, [0, 1], [0, width * 0.6]);
  const lineOpacity = interpolate(lineEntrance, [0, 1], [0, 1]);
  
  const subtitleY = interpolate(subtitleEntrance, [0, 1], [-50, 0]);
  const subtitleOpacity = interpolate(subtitleEntrance, [0, 1], [0, 1]);

  // Dynamic Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    backgroundColor: bgColor,
    fontFamily: "Oswald, sans-serif",
    textTransform: "uppercase",
  };

  const titleStyle: React.CSSProperties = {
    fontSize: titleSize,
    color: primaryColor,
    fontWeight: 700,
    letterSpacing: "0.05em",
    lineHeight: 1,
    transform: `translateY(${titleY}px)`,
    opacity: titleOpacity,
    textShadow: `0px 10px 30px ${primaryColor}40`, // Subtle glow
    textAlign: "center",
    zIndex: 2,
  };

  const subtitleStyle: React.CSSProperties = {
    fontFamily: "Montserrat, sans-serif",
    fontSize: subtitleSize,
    color: secondaryColor,
    fontWeight: 600,
    letterSpacing: "0.2em",
    marginTop: 30,
    transform: `translateY(${subtitleY}px)`,
    opacity: subtitleOpacity,
    textAlign: "center",
    zIndex: 2,
  };

  const lineStyle: React.CSSProperties = {
    height: 4,
    width: lineWidth,
    backgroundColor: accentColor,
    marginTop: 20,
    marginBottom: 10,
    opacity: lineOpacity,
    borderRadius: 2,
    boxShadow: `0px 0px 15px ${accentColor}80`, // Glow effect on line
  };

  // Mask containers to create "reveal" effect
  const titleMask: React.CSSProperties = {
    overflow: "hidden",
    paddingBottom: 20, // Space for shadow
  };

  const subtitleMask: React.CSSProperties = {
    overflow: "hidden",
    paddingTop: 10,
  };

  return (
    <AbsoluteFill style={containerStyle}>
      {/* Background Ambience (Optional Subtle Glow) */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: width * 1.5,
            height: height * 1.5,
            background: `radial-gradient(circle, ${primaryColor}15 0%, transparent 60%)`,
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            pointerEvents: "none",
            zIndex: 0,
          }}
        />
      )}

      {/* Main Content */}
      <div style={titleMask}>
        <div style={titleStyle}>{titleText}</div>
      </div>

      <div style={lineStyle} />

      <div style={subtitleMask}>
        <div style={subtitleStyle}>{subtitleText}</div>
      </div>
    </AbsoluteFill>
  );
};

export default ChampionshipTitle;